class Solution {
public:
    int longestNiceSubarray(vector<int>& nums) {
        int n = nums.size();
        int left = 0;
        int windowOr = 0;
        int ans = 0;
        for (int right = 0; right < n; right++) {
            while ((windowOr & nums[right]) != 0) {
                windowOr ^= nums[left];
                left++;
            }
            windowOr |= nums[right];
            ans = max(ans, right - left + 1);
        }
        return ans;
    }
};
